type.Commitment.toml:
[types.Commitment]
description = "Something Kestrel has promised or owes a customer account, such as a feature, a deliverable, a price term or a credit, identified by what it promises."
props = { amount_usd = "float", due_on = "date" }

type.Contact.toml:
[types.Contact]
description = "A person at a customer account whom Kestrel deals with, identified by their contact id."
props = { contact_id = "string", email = "string", full_name = "string", role = "string", title = "string" }
key = ["contact_id"]
names = ["full_name"]
identifiers = { email = "email" }

type.Conversation.toml:
[types.Conversation]
description = "A call, meeting or email exchange between Kestrel and a customer account, identified by its title."
props = { held_on = "date", risks = "string", summary = "string" }

type.Invoice.toml:
[types.Invoice]
description = "A bill issued for a subscription, identified by its invoice id."
props = { amount_usd = "float", due_on = "date", invoice_id = "string", issued_on = "date", paid_on = "date", status = "string" }
key = ["invoice_id"]
identifiers = { invoice_id = "code" }

type.Subscription.toml:
[types.Subscription]
description = "An account's paid subscription to a plan for a number of seats over a term, identified by its subscription id."
props = { cancel_reason = "string", current_term_end = "date", discount_pct = "integer", ended_on = "date", monthly_amount_usd = "float", price_per_seat_usd = "float", seats = "integer", started_on = "date", status = "string", subscription_id = "string", term_months = "integer" }
key = ["subscription_id"]
identifiers = { subscription_id = "code" }

type.Ticket.toml:
[types.Ticket]
description = "A support request raised by a customer contact, identified by its ticket id."
props = { category = "string", closed_at = "datetime", opened_at = "datetime", priority = "string", status = "string", subject = "string", ticket_id = "string" }
key = ["ticket_id"]
identifiers = { ticket_id = "code" }
